def daten_uebernehmen(apps, schema_editor):
    """Bestehende Daten an die neuen Strukturen anpassen :
    - Sujet.letzte_aktivitaet = Zeitpunkt der letzten Antwort (sonst Erstellung des Themas) ;
    - jedes alte Herz (PublicationLike) wird zur Reaktion „❤️“, damit die Zähler gleich bleiben.
    Die alten Herz-Zeilen bleiben unverändert bestehen (kein Datenverlust, Rückbau möglich)."""
    Sujet = apps.get_model("communaute", "Sujet")
    ReponseForum = apps.get_model("communaute", "ReponseForum")
    PublicationLike = apps.get_model("communaute", "PublicationLike")
    Reaktion = apps.get_model("communaute", "Reaktion")

    letzte = {}
    for sujet_id, erstellt in ReponseForum.objects.order_by("created_at").values_list(
        "sujet_id", "created_at"
    ):
        letzte[sujet_id] = erstellt
    for sujet in Sujet.objects.all().iterator():
        zeit = letzte.get(sujet.id) or sujet.created_at
        Sujet.objects.filter(pk=sujet.pk).update(letzte_aktivitaet=zeit)

    neue = [
        Reaktion(membre_id=like.membre_id, publication_id=like.publication_id, emoji="\u2764\ufe0f")
        for like in PublicationLike.objects.all().iterator()
    ]
    Reaktion.objects.bulk_create(neue, batch_size=500, ignore_conflicts=True)


